save(431,dict(paragraphs=["Pankajam Kottanath, published elsewhere as Pankajam Kottarath and K. Pankajam, writes poetry and fiction in English and Malayalam and translates from Malayalam into English. Her poetry collections include Whispering Waves, published by Writers Workshop in 2013. Her contributions to Setu also explore memory, belonging and the experience of moving between cultures.","In ‘Love And After’, intimacy meets the cruelty of public judgment. Images of a sea and a desert give way to a world where the lovers become both the accused and their own judges. The poem’s final movement imagines love surviving that judgment, turning an intimate story into a challenge to collective hypocrisy."],sources=[source('Setu — Pankajam Kottarath, April 2025','https://www.setumag.com/2025/04/pankajam-kottarath-diaspora-dual.html',['Kottarath and K. Pankajam bylines; bilingual poet/novelist; distinctive biography and award sequence match capture.','Published poems address migration, memory and belonging.'],'search_index_excerpt'),source('Boloji — Whispering Waves, review by U Atreya Sarma','https://www.boloji.com/articles/48709/whispering-waves-refreshing-waves-of-poetry',['Whispering Waves, Writers Workshop, 2013, ISBN 9789350450673.','English/Malayalam writing and Malayalam-to-English translation.'])],books=[dict(title='Whispering Waves',detail='Poetry · Writers Workshop, 2013',url='https://www.boloji.com/articles/48709/whispering-waves-refreshing-waves-of-poetry')],identity_match='Near-identical captured biography and distinctive five-award sequence match Setu Kottarath; Setu explicitly pairs this spelling with K. Pankajam. Preserve captured display name Kottanath pending editorial spelling confirmation.',poems_read=[dict(id=673,title='Love And After',basis='Full captured English original read; close reading of intimacy, judgment and final transcendence, not an assertion of autobiographical events.')],limitations=['Display-name spelling differs from external publications; no canonical name change made.','Publication totals vary by date; omitted totals and awards from added prose.','Setu direct open failed; full indexed article supplied biography and poems.','Book link is a literary review rather than a purchase link.'],research_leads=[],next_action='Author/editor to confirm preferred surname spelling and review narrative.'))
